 public static void main(String[]args)throws Exception{for(int size:List.of(2,80,398)){String factory="Lkeys/Factory;";List<org.jf.dexlib2.iface.instruction.Instruction> code=new ArrayList<>();List<ImmutableClassDef> ds=new ArrayList<>();for(int n=0;n<size;n++){String type="Lkeys/Product"+n+";";code.add(new ImmutableInstruction21c(Opcode.CONST_CLASS,0,new ImmutableTypeReference(type)));code.add(new ImmutableInstruction22t(Opcode.IF_NE,0,1,8));code.add(make(0,type));code.add(call(Opcode.INVOKE_DIRECT,type,"<init>",List.of(),"V",0));code.add(new ImmutableInstruction11x(Opcode.RETURN_OBJECT,0));ds.add(clazz(type,OBJ,List.of(),List.of(),method(type,"<init>",List.of(),"V",0x10001,1,List.of(end()),false)));}code.add(zero(0));code.add(new ImmutableInstruction11x(Opcode.RETURN_OBJECT,0));var m=method(factory,"create",List.of("Ljava/lang/Class;"),OBJ,9,2,code,false);ds.add(clazz(factory,OBJ,List.of(),List.of(),m));Path p=Files.createTempFile("class-key-",".dex");try{DexFileFactory.writeDexFile(p.toString(),new ImmutableDexFile(Opcodes.getDefault(),ds));long d=System.nanoTime()+30_000_000_000L;CapabilityIndex i=new CapabilityIndex();i.read(p,d);DexFlow f=new DexFlow(i,d);var summary=f.summary(i.resolve(factory+"->create(Ljava/lang/Class;)Ljava/lang/Object;"),v->v.kind().equals("param")?DexFlow.V.of("class","keys.Product0","Lkeys/Product0;"):v);System.out.println("size="+size+" expected=Product0-only returns="+summary.returns()+" truncated="+summary.truncated());}finally{Files.deleteIfExists(p);}}}
